1369: /// Advance scheduler deadlines/events and preempt the current thread if another
1370: /// context is ready. Called only after the timer IRQ has sent APIC EOI.
1371: pub(crate) fn timer_interrupt() {
1372:     let runtime_pointer = ACTIVE_RUNTIME.load(Ordering::Acquire);
1373:     if runtime_pointer.is_null() {
1374:         return;
1375:     }
1376: 
1377:     // The interrupt gate has cleared IF. Every ordinary scheduler mutation also
1378:     // disables IF before borrowing this runtime, so the single CPU cannot observe
1379:     // a partially updated scheduler state here.
1380:     let switch = unsafe {
1381:         let runtime = &mut *runtime_pointer;
1382:         runtime.wake_ready_events();
1383:         let Some(current) = runtime.policy.current() else {
1384:             return;
1385:         };
1386:         let old_context = runtime.current_context;
1387:         if old_context != current.slot_index() + 1 {
1388:             halt_on_stack_cleanup_failure();
1389:         }
1390:         let next = runtime
1391:             .policy
1392:             .preempt_current()
1393:             .unwrap_or_else(|_| halt_on_stack_cleanup_failure());
1394:         let next_context = next.slot_index() + 1;
1395:         runtime.current_context = next_context;
1396:         if next == current {
1397:             None
1398:         } else {
1399:             Some((
1400:                 core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
1401:                 runtime.saved_rsp[next_context],
1402:                 core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
1403:             ))
1404:         }
1405:     };
1406:     if let Some((old_rsp, new_rsp, new_fx_state)) = switch {
1407:         // SAFETY: The interrupted context's FXSAVE image was written by the IRQ
1408:         // stub before Rust ran. This suspends the handler stack and restores the
1409:         // selected context; the interrupted thread later resumes through IRETQ.
1410:         unsafe {
1411:             rustix_arch_context_switch_from_irq(old_rsp, new_rsp as *mut usize, new_fx_state)
1412:         };
