2136: #[cfg(feature = "probe-user-process")]
2137: fn finish_active_user_process<M: rustix_kernel::paging::CandidatePageTableMemory>(
2138:     state: &mut ActiveUserProcessSyscallContext,
2139:     roots: &mut rustix_kernel::paging::ProcessAddressSpaceRoots<'_, '_, '_, M>,
2140:     status: i32,
2141: ) -> i64 {
2142:     use rustix_kernel::syscall::SyscallError;
2143: 
2144:     // SAFETY: The process table remains live through this synchronous entry.
2145:     if unsafe { &mut *state.process_table }
2146:         .exit(state.process_id, status)
2147:         .is_err()
2148:     {
2149:         return SyscallError::InvalidArgument.return_value();
2150:     }
2151:     // SAFETY: The kernel CR3 was captured before entering this root, and
2152:     // interrupts remain disabled for the complete user-process run.
2153:     unsafe { arch::x86_64::cpu::write_cr3_with_global_flush(state.kernel_cr3) };
2154:     if arch::x86_64::cpu::read_cr3_raw() != state.kernel_cr3 {
2155:         halt_forever();
2156:     }
2157:     // SAFETY: The kernel root is installed and verified; no CPU can use the
2158:     // process root after this point in the single-vCPU test harness.
2159:     if unsafe { roots.mark_inactive(state.process) }.is_err() {
2160:         halt_forever();
2161:     }
2162:     // SAFETY: This exit callback runs with IF clear inside a live pinned process task.
2163:     if !unsafe { crate::kernel_threads::wake_process_exit_waiters(state.runtime_pointer) }
2164:         || (state.process_id.get() == 1
2165:             && !unsafe { crate::kernel_threads::close_process_start(state.runtime_pointer) })
2166:     {
2167:         halt_forever();
2168:     }
2169:     // SAFETY: The kernel root is active, process root is inactive, and IF=0.
2170:     unsafe { arch::x86_64::interrupts::request_user_process_exit(status) };
2171:     0
2172: }
