2174: #[cfg(feature = "probe-user-process")]
2175: extern "C" fn dispatch_active_user_process_syscall(
2176:     raw_context: *mut rustix_kernel::syscall::SyscallContext,
2177:     opaque: *mut (),
2178: ) -> i64 {
2179:     use rustix_kernel::syscall::{
2180:         decode_syscall, SyscallArguments, SyscallError, SyscallRequest, ABI_VERSION,
2181:     };
2182: 
2183:     // SAFETY: The DPL-3 entry supplies a live kernel-stack context. The runtime
2184:     // pointer is installed only for the synchronous user entry below and remains
2185:     // valid until the exit path returns to this stack.
2186:     let Some(context) = (unsafe { raw_context.as_mut() }) else {
2187:         halt_forever();
2188:     };
2189:     // SAFETY: `opaque` points to the live stack-owned runtime record registered
2190:     // before switching to the process root; callbacks cannot retain its fields.
2191:     let state_ptr = opaque.cast::<ActiveUserProcessSyscallContext>();
2192:     if state_ptr.is_null() {
2193:         halt_forever();
2194:     }
2195:     // SAFETY: The process root is active and the sanitized syscall return frame
2196:     // must resolve to executable code and a writable NX stack before any service.
2197:     let process = unsafe { core::ptr::addr_of!((*state_ptr).process).read() };
2198:     let roots_ptr = unsafe {
2199:         core::ptr::addr_of!((*state_ptr).roots).read().cast::<
2200:             rustix_kernel::paging::ProcessAddressSpaceRoots<
2201:                 '_ ,
2202:                 '_ ,
2203:                 '_ ,
2204:                 LimineHhdmCandidateMemory<'_>,
2205:             >,
2206:         >()
2207:     };
2208:     let return_state_valid = unsafe { &*roots_ptr }
2209:         .validate_user_return_state(process, context.instruction_pointer, context.stack_pointer)
2210:         .is_ok();
2211:     if !return_state_valid {
2212:         // The process root remains active until its fatal bad-return path switches
2213:         // back to the kernel root and requests the nested entry exit.
2214:         let state = unsafe { &mut *state_ptr };
2215:         let roots = unsafe { &mut *roots_ptr };
2216:         return finish_active_user_process(state, roots, 141);
2217:     }
2218:     let arguments = SyscallArguments {
2219:         rdi: context.rdi,
2220:         rsi: context.rsi,
2221:         rdx: context.rdx,
2222:         r10: context.r10,
2223:         r8: context.r8,
2224:         r9: context.r9,
2225:     };
2226:     let request = match decode_syscall(context.rax, arguments) {
2227:         Ok(request) => request,
2228:         Err(error) => return error.return_value(),
2229:     };
2230:     if let SyscallRequest::Wait {
2231:         child_pid,
2232:         status_address,
2233:     } = request
2234:     {
2235:         return dispatch_user_wait(state_ptr, child_pid, status_address);
2236:     }
2237:     if let SyscallRequest::Spawn {
2238:         image_address,
2239:         image_length,
2240:         stack_pages,
2241:     } = request
2242:     {
2243:         return dispatch_user_spawn(state_ptr, image_address, image_length, stack_pages);
2244:     }
2245: 
2246:     // These mutable references are created only after the blocking-wait branch
2247:     // returns; the child runner may re-enter the callback with this same state.
2248:     let state = unsafe { &mut *state_ptr };
2249:     let roots = unsafe { &mut *roots_ptr };
2250:     let user_memory = unsafe { &mut *state.user_memory.cast::<LimineHhdmUserFrameMemory<'_>>() };
2251:     match request {
2252:         SyscallRequest::AbiVersion => ABI_VERSION as i64,
2253:         SyscallRequest::Write {
2254:             fd,
2255:             user_buffer,
2256:             length,
2257:         } => {
2258:             let stream =
2259:                 // SAFETY: The process table remains live and IF is clear for this
2260:                 // synchronous single-vCPU dispatch.
2261:                 unsafe { &*state.process_table }.descriptor_stream(state.process_id, fd);
2262:             let Some(stream) = stream else {
2263:                 return SyscallError::BadFileDescriptor.return_value();
2264:             };
2265:             let mut output = SerialProcessProbeOutput;
2266:             // SAFETY: The kernel stack is not allocator-usable user memory; the
2267:             // service copies via owned frame tokens and never dereferences user VA.
2268:             match unsafe {
2269:                 rustix_kernel::syscall::write_user_buffer_to_stream(
2270:                     roots,
2271:                     state.process,
2272:                     stream,
2273:                     user_buffer,
2274:                     length,
2275:                     user_memory,
2276:                     &mut output,
2277:                 )
2278:             } {
2279:                 Ok(written) => written as i64,
2280:                 Err(error) => error.return_value(),
2281:             }
2282:         }
2283:         SyscallRequest::Close { fd } => {
2284:             // SAFETY: Process-table mutation is serialized by IF=0 on the single CPU.
2285:             match unsafe { &mut *state.process_table }.close_descriptor(state.process_id, fd) {
2286:                 Ok(()) => 0,
2287:                 Err(error) => descriptor_error_to_syscall(error).return_value(),
2288:             }
2289:         }
2290:         SyscallRequest::Duplicate { fd } => {
2291:             // SAFETY: Process-table mutation is serialized by IF=0 on the single CPU.
2292:             match unsafe { &mut *state.process_table }.duplicate_descriptor(state.process_id, fd) {
2293:                 Ok(duplicate) => duplicate as i64,
2294:                 Err(error) => descriptor_error_to_syscall(error).return_value(),
2295:             }
2296:         }
2297:         SyscallRequest::Exit { status } => finish_active_user_process(state, roots, status),
2298:         SyscallRequest::Mmap { length } => {
2299:             match map_anonymous_user_page(state, roots, user_memory, length) {
2300:                 Ok(address) => address as i64,
2301:                 Err(error) => error.return_value(),
2302:             }
2303:         }
2304:         SyscallRequest::Munmap { address } => {
2305:             match unmap_anonymous_user_page(state, roots, user_memory, address) {
2306:                 Ok(()) => 0,
2307:                 Err(error) => error.return_value(),
2308:             }
2309:         }
2310:         SyscallRequest::MmapRegion { length } => {
2311:             match map_anonymous_user_region(state, roots, user_memory, length) {
2312:                 Ok(address) => address as i64,
2313:                 Err(error) => error.return_value(),
2314:             }
2315:         }
2316:         SyscallRequest::MunmapRegion { address, length } => {
2317:             match unmap_anonymous_user_region(state, roots, user_memory, address, length) {
2318:                 Ok(()) => 0,
2319:                 Err(error) => error.return_value(),
2320:             }
2321:         }
2322:         SyscallRequest::Spawn { .. } => unreachable!("spawn is dispatched before mutable borrows"),
2323:         SyscallRequest::Wait { .. } => unreachable!("wait is dispatched before mutable borrows"),
2324:     }
2325: }
