2415: #[cfg(feature = "probe-user-process")]
2416: fn prepare_spawned_user_process<M: rustix_kernel::paging::CandidatePageTableMemory>(
2417:     state: &mut ActiveUserProcessSyscallContext,
2418:     roots: &mut rustix_kernel::paging::ProcessAddressSpaceRoots<'_, '_, '_, M>,
2419:     slot: *mut SpawnedProcessTask,
2420:     image: &[u8],
2421:     stack_pages: usize,
2422: ) -> Result<u64, rustix_kernel::syscall::SyscallError> {
2423:     use rustix_kernel::paging::CachePolicy;
2424:     use rustix_kernel::process::UserProgramPrepareErrorKind;
2425:     use rustix_kernel::syscall::SyscallError;
2426: 
2427:     let Some(allocator) = (unsafe { state.allocator.as_mut() }) else {
2428:         return Err(SyscallError::Io);
2429:     };
2430:     let Some(user_memory) = (unsafe {
2431:         state
2432:             .user_memory
2433:             .cast::<LimineHhdmUserFrameMemory<'_>>()
2434:             .as_mut()
2435:     }) else {
2436:         return Err(SyscallError::Io);
2437:     };
2438:     let Some(mtrr_layout) = (unsafe { state.mtrr_layout.as_ref() }) else {
2439:         return Err(SyscallError::Io);
2440:     };
2441:     let mut select_cache = |mapping: rustix_kernel::paging::ValidatedMappingRange| {
2442:         mapping
2443:             .select_cache_attributes(
2444:                 CachePolicy::WriteBack,
2445:                 state.pat,
2446:                 mtrr_layout,
2447:                 state.normal_caching,
2448:             )
2449:             .map_err(|_| "no uniform write-back cache policy for spawned process page")
2450:     };
2451:     let stack_bytes = (stack_pages as u64)
2452:         .checked_mul(rustix_kernel::paging::PAGE_SIZE)
2453:         .ok_or(SyscallError::Overflow)?;
2454:     let lower_half_shift = u32::from(
2455:         state
2456:             .virtual_address_bits
2457:             .checked_sub(1)
2458:             .ok_or(SyscallError::InvalidArgument)?,
2459:     );
2460:     let stack_top = 1u64
2461:         .checked_shl(lower_half_shift)
2462:         .ok_or(SyscallError::InvalidArgument)?;
2463:     let stack_base = stack_top
2464:         .checked_sub(stack_bytes)
2465:         .ok_or(SyscallError::InvalidArgument)?;
2466:     let program = match rustix_kernel::process::prepare_user_program(
2467:         roots,
2468:         allocator,
2469:         user_memory,
2470:         image,
2471:         stack_base,
2472:         stack_pages as u64,
2473:         1,
2474:         state.physical_address_bits,
2475:         state.virtual_address_bits,
2476:         arch::x86_64::interrupts::USER_CODE_SELECTOR,
2477:         arch::x86_64::interrupts::USER_DATA_SELECTOR,
2478:         &mut select_cache,
2479:     ) {
2480:         Ok(program) => program,
2481:         Err(failure) => {
2482:             let error = match failure.kind {
2483:                 UserProgramPrepareErrorKind::InvalidElf
2484:                 | UserProgramPrepareErrorKind::RegionReservation
2485:                 | UserProgramPrepareErrorKind::StackGuard
2486:                 | UserProgramPrepareErrorKind::InvalidInitialState
2487:                 | UserProgramPrepareErrorKind::InvalidIretFrame => SyscallError::InvalidArgument,
2488:                 UserProgramPrepareErrorKind::RootCreation
2489:                 | UserProgramPrepareErrorKind::StackAllocation => SyscallError::OutOfMemory,
2490:                 _ => SyscallError::Io,
2491:             };
2492:             if failure.cleanup(roots, allocator).is_err() {
2493:                 halt_forever();
2494:             }
2495:             return Err(error);
2496:         }
2497:     };
2498: 
2499:     let process_table_ptr = state.process_table;
2500:     let Some(process_table) = (unsafe { process_table_ptr.as_mut() }) else {
2501:         roots
2502:             .destroy(allocator, program.process)
2503:             .unwrap_or_else(|_| halt_forever());
2504:         return Err(SyscallError::Io);
2505:     };
2506:     let child_id = match process_table.spawn(state.process_id) {
2507:         Ok(pid) => pid,
2508:         Err(rustix_kernel::process::ProcessTableError::Capacity) => {
2509:             roots
2510:                 .destroy(allocator, program.process)
2511:                 .unwrap_or_else(|_| halt_forever());
2512:             return Err(SyscallError::OutOfMemory);
2513:         }
2514:         Err(_) => {
2515:             roots
2516:                 .destroy(allocator, program.process)
2517:                 .unwrap_or_else(|_| halt_forever());
2518:             return Err(SyscallError::InvalidArgument);
2519:         }
2520:     };
2521:     let child_stack_index = match usize::try_from(child_id.get().checked_sub(1).unwrap_or(u64::MAX))
2522:     {
2523:         Ok(index) if index < rustix_kernel::process::MAX_PROCESSES => index,
2524:         _ => {
2525:             rollback_unstarted_child(process_table, child_id);
2526:             roots
2527:                 .destroy(allocator, program.process)
2528:                 .unwrap_or_else(|_| halt_forever());
2529:             return Err(SyscallError::OutOfMemory);
2530:         }
2531:     };
2532:     let child_stack_top = unsafe { *state.kernel_entry_stack_tops.add(child_stack_index) };
2533:     let child_root_address = match roots.root_physical_address(program.process) {
2534:         Ok(address) => address,
2535:         Err(_) => {
2536:             rollback_unstarted_child(process_table, child_id);
2537:             roots
2538:                 .destroy(allocator, program.process)
2539:                 .unwrap_or_else(|_| halt_forever());
2540:             return Err(SyscallError::Io);
2541:         }
2542:     };
2543:     let process_cr3 = match rustix_kernel::paging::encode_cr3_value(
2544:         child_root_address,
2545:         state.cr3_low_bits,
2546:         state.physical_address_bits,
2547:     ) {
2548:         Ok(value) => value,
2549:         Err(_) => {
2550:             rollback_unstarted_child(process_table, child_id);
2551:             roots
2552:                 .destroy(allocator, program.process)
2553:                 .unwrap_or_else(|_| halt_forever());
2554:             return Err(SyscallError::Io);
2555:         }
2556:     };
2557: 
2558:     // SAFETY: The slot remains stable on the outer probe stack until the task
2559:     // runtime returns, and it has not previously been initialized or published.
2560:     unsafe {
2561:         core::ptr::addr_of_mut!((*slot).regions)
2562:             .write(core::mem::MaybeUninit::new(program.regions));
2563:         core::ptr::addr_of_mut!((*slot).context).write(core::mem::MaybeUninit::new(
2564:             ActiveUserProcessSyscallContext {
2565:                 roots: state.roots,
2566:                 kernel_entry_stack_tops: state.kernel_entry_stack_tops,
2567:                 cr3_low_bits: state.cr3_low_bits,
2568:                 user_memory: state.user_memory,
2569:                 allocator: state.allocator,
2570:                 user_regions: core::ptr::addr_of_mut!((*slot).regions)
2571:                     .cast::<rustix_kernel::process::UserRegionTable>(),
2572:                 process_table: state.process_table,
2573:                 mtrr_layout: state.mtrr_layout,
2574:                 process: program.process,
2575:                 process_id: child_id,
2576:                 kernel_cr3: state.kernel_cr3,
2577:                 process_cr3,
2578:                 kernel_entry_stack_top: child_stack_top,
2579:                 runtime_pointer: core::ptr::null_mut(),
2580:                 user_frame: program.user_frame,
2581:                 child_context: state.child_context,
2582:                 pat: state.pat,
2583:                 normal_caching: state.normal_caching,
2584:                 physical_address_bits: state.physical_address_bits,
2585:                 virtual_address_bits: state.virtual_address_bits,
2586:             },
2587:         ));
2588:         core::ptr::addr_of_mut!((*slot).root_owned).write(true);
2589:         core::ptr::addr_of_mut!((*slot).ready).write(true);
2590:     }
2591:     // SAFETY: The child context and all referenced storage are initialized before
2592:     // publishing the start event; the pinned scheduler runtime remains live.
2593:     if !unsafe { crate::kernel_threads::wake_process_start_waiter(state.runtime_pointer) } {
2594:         halt_forever();
2595:     }
2596:     Ok(child_id.get())
2597: }
