3436: #[cfg(feature = "probe-user-process")]
3437: fn probe_user_process_root_with_tasks<M: rustix_kernel::paging::CandidatePageTableMemory>(
3438:     candidate: &mut rustix_kernel::paging::CandidatePageTables<'_, M>,
3439:     memory_map: &rustix_kernel::memory::MemoryMap,
3440:     allocator: &mut rustix_kernel::frame::FrameAllocator,
3441:     cpu_info: &arch::x86_64::cpu::CpuInfo,
3442:     hhdm_offset: u64,
3443:     config: rustix_kernel::paging::PageWalkConfig,
3444:     mut process_tasks: core::pin::Pin<&mut crate::kernel_threads::PreparedProcessTasks>,
3445: ) -> Result<(), &'static str> {
3446:     use rustix_kernel::paging::{CachePolicy, MtrrState, PatLayout, ProcessAddressSpaceRoots};
3447: 
3448:     let process_setup_free_frames = allocator.free_frames();
3449:     let mut kernel_entry_stack_tops = [0; rustix_kernel::process::MAX_PROCESSES];
3450:     for (index, stack_top) in kernel_entry_stack_tops.iter_mut().enumerate() {
3451:         *stack_top = process_kernel_entry_stack_top_for_slot(candidate, index)
3452:             .ok_or("per-process kernel entry stack is not mapped RW/NX and supervisor-only")?;
3453:     }
3454:     let kernel_half = candidate
3455:         .share_supervisor_kernel_half()
3456:         .map_err(|_| "active kernel half could not be shared safely")?;
3457:     let physical_address_bits = cpu_info
3458:         .physical_address_bits
3459:         .ok_or("physical address width unavailable")?;
3460:     let pat = match cpu_info.pat_msr_value {
3461:         Some(value) => PatLayout::from_msr_value(value)
3462:             .map_err(|_| "PAT state is invalid for process mappings")?,
3463:         None => return Err("PAT state unavailable for process mappings"),
3464:     };
3465:     let mtrr_layout = match &cpu_info.mtrr {
3466:         MtrrState::Captured(registers) => registers
3467:             .validated_layout(physical_address_bits)
3468:             .map_err(|_| "MTRR state is invalid for process mappings")?,
3469:         _ => return Err("MTRR state unavailable for process mappings"),
3470:     };
3471:     let mut select_cache = |mapping: rustix_kernel::paging::ValidatedMappingRange| {
3472:         mapping
3473:             .select_cache_attributes(
3474:                 CachePolicy::WriteBack,
3475:                 pat,
3476:                 &mtrr_layout,
3477:                 cpu_info.normal_caching,
3478:             )
3479:             .map_err(|_| "no uniform write-back cache policy for process page")
3480:     };
3481:     let mut process_memory = LimineHhdmCandidateMemory {
3482:         memory_map,
3483:         hhdm_offset,
3484:         physical_address_bits,
3485:         virtual_address_bits: cpu_info.active_linear_address_bits,
3486:     };
3487:     let mut roots = match ProcessAddressSpaceRoots::new(&kernel_half, &mut process_memory, config) {
3488:         Ok(roots) => roots,
3489:         Err(failure) => {
3490:             if let Some(frame) = failure.frame {
3491:                 allocator
3492:                     .deallocate(frame)
3493:                     .map_err(|_| "process-root manager frame could not be reclaimed")?;
3494:             }
3495:             return Err("process-root manager creation failed");
3496:         }
3497:     };
3498: 
3499:     let mut user_memory = LimineHhdmUserFrameMemory {
3500:         memory_map,
3501:         hhdm_offset,
3502:         physical_address_bits: Some(physical_address_bits),
3503:         virtual_address_bits: cpu_info.active_linear_address_bits,
3504:     };
3505:     const USER_STACK_BASE: u64 = 0x0000_7fff_ffff_f000;
3506:     let init_program = match prepare_user_program(
3507:         &mut roots,
3508:         allocator,
3509:         &mut user_memory,
3510:         INIT_ELF_IMAGE,
3511:         USER_STACK_BASE,
3512:         physical_address_bits,
3513:         cpu_info.active_linear_address_bits,
3514:         &mut select_cache,
3515:     ) {
3516:         Ok(program) => program,
3517:         Err(error) => return Err(error),
3518:     };
3519:     let process = init_program.process;
3520:     let mut user_regions = init_program.regions;
3521:     let user_frame = init_program.user_frame;
3522: 
3523:     let mut process_table = rustix_kernel::process::ProcessTable::new();
3524:     let process_id = process_table
3525:         .create_initial()
3526:         .map_err(|_| "initial process record could not be created")?;
3527:     let process_kernel_stack_top = kernel_entry_stack_tops[0];
3528:     kprintln!(
3529:         "Ring 3 entry stack validated: pid={}, entry={:#x}",
3530:         process_id.get(),
3531:         process_kernel_stack_top
3532:     );
3533: 
3534:     let root_address = match roots.root_physical_address(process) {
3535:         Ok(address) => address,
3536:         Err(_) => {
3537:             roots
3538:                 .destroy(allocator, process)
3539:                 .map_err(|_| "process root could not be destroyed after root lookup failed")?;
3540:             return Err("process root address is unavailable");
3541:         }
3542:     };
3543:     let kernel_cr3 = arch::x86_64::cpu::read_cr3_raw();
3544:     let kernel_cr3_root = match rustix_kernel::paging::parse_cr3_root(
3545:         kernel_cr3,
3546:         Some(physical_address_bits),
3547:         cpu_info.pcid_enabled,
3548:     ) {
3549:         Ok(root) => root,
3550:         Err(_) => {
3551:             roots.destroy(allocator, process).map_err(|_| {
3552:                 "process root could not be destroyed after kernel CR3 validation failed"
3553:             })?;
3554:             return Err("active kernel CR3 could not be validated");
3555:         }
3556:     };
3557:     let process_cr3 = match rustix_kernel::paging::encode_cr3_value(
3558:         root_address,
3559:         kernel_cr3_root.low_bits(),
3560:         physical_address_bits,
3561:     ) {
3562:         Ok(value) => value,
3563:         Err(_) => {
3564:             roots
3565:                 .destroy(allocator, process)
3566:                 .map_err(|_| "process root could not be destroyed after CR3 encoding failed")?;
3567:             return Err("process CR3 encoding failed");
3568:         }
3569:     };
3570: 
3571:     let mut spawned_child_tasks: [SpawnedProcessTask; SPAWNED_CHILD_SLOTS] =
3572:         core::array::from_fn(|_| SpawnedProcessTask {
3573:             ready: false,
3574:             root_owned: false,
3575:             regions: core::mem::MaybeUninit::uninit(),
3576:             context: core::mem::MaybeUninit::uninit(),
3577:         });
3578:     let mut process_context = ActiveUserProcessSyscallContext {
3579:         roots: core::ptr::addr_of_mut!(roots).cast(),
3580:         kernel_entry_stack_tops: core::ptr::addr_of!(kernel_entry_stack_tops).cast(),
3581:         cr3_low_bits: kernel_cr3_root.low_bits(),
3582:         user_memory: core::ptr::addr_of_mut!(user_memory).cast(),
3583:         allocator: core::ptr::addr_of_mut!(*allocator),
3584:         user_regions: core::ptr::addr_of_mut!(user_regions),
3585:         process_table: core::ptr::addr_of_mut!(process_table),
3586:         mtrr_layout: core::ptr::addr_of!(mtrr_layout),
3587:         process,
3588:         process_id,
3589:         kernel_cr3,
3590:         process_cr3,
3591:         kernel_entry_stack_top: process_kernel_stack_top,
3592:         runtime_pointer: core::ptr::null_mut(),
3593:         user_frame,
3594:         child_context: core::ptr::addr_of_mut!(spawned_child_tasks).cast(),
3595:         pat,
3596:         normal_caching: cpu_info.normal_caching,
3597:         physical_address_bits,
3598:         virtual_address_bits: cpu_info.active_linear_address_bits,
3599:     };
3600:     // SAFETY: IF was disabled by the caller; all pointer targets remain live
3601:     // until the synchronous user entry returns through its exit syscall.
3602:     if unsafe {
3603:         arch::x86_64::interrupts::install_user_syscall_handler(
3604:             dispatch_active_user_process_syscall,
3605:             dispatch_active_user_process_exception,
3606:         )
3607:     }
3608:     .is_err()
3609:     {
3610:         roots.destroy(allocator, process).map_err(|_| {
3611:             "process root could not be destroyed after syscall handler setup failed"
3612:         })?;
3613:         return Err("user syscall handler setup failed");
3614:     }
3615:     let mut tasks: [(crate::kernel_threads::ThreadEntry, usize);
3616:         rustix_kernel::process::MAX_PROCESSES] =
3617:         [(run_user_process_task, 0); rustix_kernel::process::MAX_PROCESSES];
3618:     tasks[0].1 = core::ptr::addr_of_mut!(process_context) as usize;
3619:     for index in 0..SPAWNED_CHILD_SLOTS {
3620:         tasks[index + 1] = (
3621:             run_deferred_user_process_task,
3622:             core::ptr::addr_of_mut!(spawned_child_tasks[index]) as usize,
3623:         );
3624:     }
3625:     if let Err(error) =
3626:         crate::kernel_threads::run_prepared_processes(process_tasks.as_mut(), &tasks)
3627:     {
3628:         // No process entry began if task preparation failed; the process roots
3629:         // remain inactive and can be reclaimed before returning the setup error.
3630:         unsafe { arch::x86_64::interrupts::clear_user_syscall_handler() };
3631:         destroy_spawned_child_roots(&mut roots, allocator, &mut spawned_child_tasks)?;
3632:         roots
3633:             .destroy(allocator, process)
3634:             .map_err(|_| "inactive process root could not be destroyed after scheduler failure")?;
3635:         return Err(error);
3636:     }
3637:     if arch::x86_64::cpu::read_cr3_raw() != kernel_cr3 {
3638:         halt_forever();
3639:     }
3640:     // All process tasks returned through their user-exit trampolines, and the
3641:     // scheduler has reclaimed its own guarded stacks before the callback clears.
3642:     unsafe { arch::x86_64::interrupts::clear_user_syscall_handler() };
3643:     let exit_status = match process_table.state(process_id) {
3644:         Some(rustix_kernel::process::ProcessState::Exited(status)) => status,
3645:         _ => {
3646:             destroy_spawned_child_roots(&mut roots, allocator, &mut spawned_child_tasks)?;
3647:             roots.destroy(allocator, process).map_err(|_| {
3648:                 "inactive process root could not be destroyed after missing init exit"
3649:             })?;
3650:             return Err("init process task returned without recording its exit");
3651:         }
3652:     };
3653:     let wait_result =
3654:         match process_table.try_wait(rustix_kernel::process::KERNEL_PROCESS_ID, process_id.get()) {
3655:             Ok(result) => result,
3656:             Err(_) => {
3657:                 destroy_spawned_child_roots(&mut roots, allocator, &mut spawned_child_tasks)?;
3658:                 roots.destroy(allocator, process).map_err(|_| {
3659:                     "inactive process root could not be destroyed after wait failed"
3660:                 })?;
3661:                 return Err("kernel wait could not inspect the init process");
3662:             }
3663:         };
3664:     #[cfg(any(
3665:         feature = "probe-user-fault",
3666:         feature = "probe-user-page-fault",
3667:         feature = "probe-user-general-protection",
3668:         feature = "probe-user-divide-error"
3669:     ))]
3670:     let expected_status = 128 + PROBE_USER_FAULT_VECTOR as i32;
3671:     #[cfg(not(any(
3672:         feature = "probe-user-fault",
3673:         feature = "probe-user-page-fault",
3674:         feature = "probe-user-general-protection",
3675:         feature = "probe-user-divide-error"
3676:     )))]
3677:     let expected_status = 42;
3678:     if !matches!(
3679:         wait_result,
3680:         rustix_kernel::process::WaitResult::Exited { pid, status }
3681:             if pid == process_id && status == exit_status && status == expected_status
3682:     ) {
3683:         kprintln!(
3684:             "process wait validation mismatch: result={:?}, init pid={}, trampoline status={}, expected status={}",
3685:             wait_result,
3686:             process_id.get(),
3687:             exit_status,
3688:             expected_status
3689:         );
3690:         destroy_spawned_child_roots(&mut roots, allocator, &mut spawned_child_tasks)?;
3691:         roots
3692:             .destroy(allocator, process)
3693:             .map_err(|_| "inactive process root could not be destroyed after wait mismatch")?;
3694:         return Err("init exit status was not retained and reaped as expected");
3695:     }
3696:     for slot in &spawned_child_tasks {
