            halt_forever();
        }
        let roots = unsafe { &mut *roots_ptr };
        let state = unsafe { &*state_ptr };
        switch_kernel_to_process_root(state, roots);
        if !woke {
            return SyscallError::Io.return_value();
        }
    };

