fn exec_with(
    image_address: u64,
    image_length: usize,
    stack_pages: usize,
    invoke: impl FnOnce(u64, [u64; 6]) -> i64,
) -> Result<core::convert::Infallible, SyscallError> {
    if image_length == 0 || !(1..=MAX_INITIAL_STACK_PAGES).contains(&stack_pages) {
        return Err(SyscallError::InvalidArgument);
    }
    if image_length > MAX_SPAWN_IMAGE_SIZE {
        return Err(SyscallError::ArgumentListTooLong);
    }
    let result = invoke(
        SYS_EXEC,
        [
            image_address,
            image_length as u64,
            stack_pages as u64,
            0,
            0,
            0,
        ],
    );
    // A successful exec replaces the process and never returns here.
    Err(decode_result(result).unwrap_err())
}

